CREATE TABLE IF NOT EXISTS schema_migrations(version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE programs(id text PRIMARY KEY, title text NOT NULL, version text NOT NULL, status text NOT NULL DEFAULT 'draft');
CREATE TABLE competencies(code text PRIMARY KEY, program_id text NOT NULL REFERENCES programs, title text NOT NULL);
CREATE TABLE indicators(code text PRIMARY KEY, competency_code text NOT NULL REFERENCES competencies, title text NOT NULL, target_level integer NOT NULL CHECK(target_level BETWEEN 1 AND 3), source jsonb NOT NULL DEFAULT '{}');
CREATE TABLE users(id text PRIMARY KEY, login text UNIQUE NOT NULL, name text NOT NULL, password_hash text NOT NULL, force_reset boolean NOT NULL DEFAULT true, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE roles(code text PRIMARY KEY, title text NOT NULL);
CREATE TABLE user_roles(user_id text NOT NULL REFERENCES users, role_code text NOT NULL REFERENCES roles, PRIMARY KEY(user_id,role_code));
CREATE TABLE groups(id text PRIMARY KEY, title text UNIQUE NOT NULL, year integer NOT NULL CHECK(year BETWEEN 1 AND 4), source text NOT NULL);
CREATE TABLE group_members(group_id text NOT NULL REFERENCES groups, user_id text NOT NULL REFERENCES users, PRIMARY KEY(group_id,user_id));
CREATE TABLE courses(id text PRIMARY KEY, program_id text NOT NULL REFERENCES programs, title text NOT NULL, year integer NOT NULL, semesters jsonb NOT NULL, status text NOT NULL DEFAULT 'planned', source text NOT NULL);
CREATE TABLE enrollments(course_id text NOT NULL REFERENCES courses, user_id text NOT NULL REFERENCES users, PRIMARY KEY(course_id,user_id));
CREATE TABLE staff_scopes(user_id text NOT NULL REFERENCES users, course_id text NOT NULL REFERENCES courses, group_id text NOT NULL REFERENCES groups, role_code text NOT NULL REFERENCES roles, PRIMARY KEY(user_id,course_id,group_id,role_code));
CREATE TABLE sessions(token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users, expires_at timestamptz NOT NULL);
CREATE TABLE login_limits(key_hash text PRIMARY KEY, failures integer NOT NULL, until_at timestamptz NOT NULL);
CREATE TABLE learning_units(id text PRIMARY KEY, course_id text NOT NULL REFERENCES courses, title text NOT NULL, position integer NOT NULL, semester integer NOT NULL, description text NOT NULL, version integer NOT NULL DEFAULT 1);
CREATE TABLE prerequisites(unit_id text NOT NULL REFERENCES learning_units, required_unit_id text NOT NULL REFERENCES learning_units, kind text NOT NULL CHECK(kind IN ('strict','recommended','corequisite')), min_level integer NOT NULL DEFAULT 1, PRIMARY KEY(unit_id,required_unit_id), CHECK(unit_id<>required_unit_id));
CREATE TABLE tasks(id text PRIMARY KEY, unit_id text NOT NULL REFERENCES learning_units, title text NOT NULL, level integer NOT NULL CHECK(level BETWEEN 1 AND 3), kind text NOT NULL, statement text NOT NULL, starter text NOT NULL, rubric jsonb NOT NULL, tests jsonb NOT NULL, reference_code text NOT NULL, version integer NOT NULL DEFAULT 1, published boolean NOT NULL DEFAULT true);
CREATE TABLE task_indicators(task_id text NOT NULL REFERENCES tasks, indicator_code text NOT NULL REFERENCES indicators, weight numeric NOT NULL CHECK(weight>0 AND weight<=1), status text NOT NULL DEFAULT 'proposed', PRIMARY KEY(task_id,indicator_code));
CREATE TABLE hypotheses(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users, task_id text NOT NULL REFERENCES tasks, prediction text NOT NULL, rationale text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE artifacts(id text PRIMARY KEY, owner_id text NOT NULL REFERENCES users, task_id text NOT NULL REFERENCES tasks, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,task_id));
CREATE TABLE artifact_revisions(id text PRIMARY KEY, artifact_id text NOT NULL REFERENCES artifacts, number integer NOT NULL, code text NOT NULL, explanation text NOT NULL, assistance text NOT NULL CHECK(assistance IN ('independent','reference','llm','tutor')), content_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(artifact_id,number));
CREATE TABLE attempts(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users, task_id text NOT NULL REFERENCES tasks, revision_id text UNIQUE NOT NULL REFERENCES artifact_revisions, hypothesis_id text NOT NULL REFERENCES hypotheses, task_version integer NOT NULL, status text NOT NULL DEFAULT 'submitted', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE code_runs(id text PRIMARY KEY, attempt_id text NOT NULL REFERENCES attempts, status text NOT NULL CHECK(status IN ('queued','running','passed','failed','error','unavailable')), result jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE simulator_runs(id text PRIMARY KEY, hypothesis_id text NOT NULL REFERENCES hypotheses, user_id text NOT NULL REFERENCES users, parameters jsonb NOT NULL, measurements jsonb NOT NULL, conclusion text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE comparisons(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users, revision_id text NOT NULL REFERENCES artifact_revisions, source text NOT NULL CHECK(source IN ('reference','llm')), generated_code text NOT NULL, conclusion text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reviews(id text PRIMARY KEY, attempt_id text NOT NULL REFERENCES attempts, reviewer_id text NOT NULL REFERENCES users, score numeric NOT NULL CHECK(score>=0 AND score<=100), independent boolean NOT NULL, transfer boolean NOT NULL DEFAULT false, feedback text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE evidence(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users, indicator_code text NOT NULL REFERENCES indicators, review_id text NOT NULL REFERENCES reviews, task_id text NOT NULL REFERENCES tasks, level integer NOT NULL, success numeric NOT NULL CHECK(success BETWEEN 0 AND 1), independent boolean NOT NULL, transfer boolean NOT NULL, source_status text NOT NULL DEFAULT 'proposed_mapping', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(review_id,indicator_code));
CREATE TABLE mastery_snapshots(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users, indicator_code text NOT NULL REFERENCES indicators, model_version text NOT NULL, state jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE trajectory_decisions(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users, model_version text NOT NULL, recommendation jsonb NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE journal_sources(id text PRIMARY KEY, file_name text NOT NULL, sha256 text UNIQUE NOT NULL, imported_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE journal_observations(id text PRIMARY KEY, source_id text NOT NULL REFERENCES journal_sources, user_id text REFERENCES users, group_id text NOT NULL REFERENCES groups, course_id text NOT NULL REFERENCES courses, sheet text NOT NULL, cell text NOT NULL, raw_value text NOT NULL, meaning text NOT NULL DEFAULT 'unclassified', UNIQUE(source_id,sheet,cell));
CREATE TABLE grade_entries(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users, course_id text NOT NULL REFERENCES courses, review_id text UNIQUE REFERENCES reviews, score numeric NOT NULL, author_id text NOT NULL REFERENCES users, note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE learning_events(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users, course_id text REFERENCES courses, kind text NOT NULL, object_id text, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE llm_interactions(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users, task_id text NOT NULL REFERENCES tasks, provider text NOT NULL, model text NOT NULL, purpose text NOT NULL, prompt_hash text NOT NULL, response text NOT NULL, consent boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log(id text PRIMARY KEY, actor_id text REFERENCES users, action text NOT NULL, object_id text, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE appeals(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users, attempt_id text NOT NULL REFERENCES attempts, message text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id text PRIMARY KEY, user_id text NOT NULL REFERENCES users, title text NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE research_consents(user_id text PRIMARY KEY REFERENCES users, granted boolean NOT NULL DEFAULT false, protocol_version text NOT NULL, changed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE research_experiments(id text PRIMARY KEY, owner_id text NOT NULL REFERENCES users, title text NOT NULL, protocol jsonb NOT NULL, status text NOT NULL DEFAULT 'draft');
CREATE INDEX events_user_time ON learning_events(user_id,created_at);
CREATE INDEX attempts_user_task ON attempts(user_id,task_id);
CREATE INDEX evidence_user ON evidence(user_id,indicator_code);
CREATE INDEX observations_user ON journal_observations(user_id);
CREATE INDEX scope_user ON staff_scopes(user_id,course_id);
